/**
 * @file Disallow redundant return statements
 * @author Teddy Katz
 */
import dependency0 from './utils/ast-utils';
import dependency1 from './utils/fix-tracker';
import type {
    CodePath, CodePathSegment, Fixer, LegacyRule, Node,
} from '../../../types';

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const astUtils = dependency0;
const FixTracker = dependency1;

//------------------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------------------

/**
 * Removes the given element from the array.
 * @param array The source array to remove.
 * @param element The target item to remove.
 */
function remove(array: Node<'ReturnStatement'>[], element: Node) {
    const index = array.findIndex((node) => node === element);

    if (index !== -1) {
        array.splice(index, 1);
    }
}

/**
 * Checks whether it can remove the given return statement or not.
 * @param node The return statement node to check.
 * @returns `true` if the node is removable.
 */
function isRemovable(node: Node<'ReturnStatement'>) {
    return astUtils.STATEMENT_LIST_PARENTS.has(node.parent.type);
}

/**
 * Checks whether the given return statement is in a `finally` block or not.
 * @param node The return statement node to check.
 * @returns `true` if the node is in a `finally` block.
 */
function isInFinally(node: Node<'ReturnStatement'>) {
    for (
        let currentNode: Node = node;
        currentNode && currentNode.parent && !astUtils.isFunction(currentNode);
        currentNode = currentNode.parent
    ) {
        if (
            currentNode.parent.type === 'TryStatement'
            && currentNode.parent.finalizer === currentNode
        ) {
            return true;
        }
    }

    return false;
}

/**
 * Checks all segments in a set and returns true if any are reachable.
 * @param segments The segments to check.
 * @returns True if any segment is reachable; false otherwise.
 */
function isAnySegmentReachable(segments: Set<CodePathSegment>) {
    return Array.from(segments).some((segment) => segment.reachable);
}

//------------------------------------------------------------------------------
// Rule Definition
//------------------------------------------------------------------------------

const rule: LegacyRule<[]> = {
    meta: {
        type: 'suggestion',

        docs: {
            description: 'Disallow redundant return statements',
            recommended: false,
            url: 'https://eslint.org/docs/latest/rules/no-useless-return',
        },

        fixable: 'code',
        schema: [],

        messages: {
            unnecessaryReturn: 'Unnecessary return statement.',
        },
    },

    create(context) {
        const segmentInfoMap = new WeakMap<CodePathSegment, {
            returned: boolean;
            uselessReturns: Node[];
        }>();
        const { sourceCode } = context;
        interface ScopeInfoState {
            upper: ScopeInfoState | null;
            uselessReturns: Node<'ReturnStatement'>[];
            traversedTryBlockStatements: Node<'BlockStatement' | 'TryStatement'>[];
            codePath: CodePath;
            currentSegments: Set<CodePathSegment>;
        }
        let scopeInfo: ScopeInfoState | null = null;

        /**
         * Checks whether the given segment is terminated by a return statement or not.
         * @param segment The segment to check.
         * @returns `true` if the segment is terminated by a return statement, or if it's still a part of
         * unreachable.
         */
        function isReturned(segment: CodePathSegment) {
            const info = segmentInfoMap.get(segment);

            return !info || info.returned;
        }

        /**
         * Collects useless return statements from the given previous segments.
         *
         * A previous segment may be an unreachable segment.
         * In that case, the information object of the unreachable segment is not
         * initialized because `onCodePathSegmentStart` event is not notified for
         * unreachable segments.
         * This goes to the previous segments of the unreachable segment recursively
         * if the unreachable segment was generated by a return statement. Otherwise,
         * this ignores the unreachable segment.
         *
         * This behavior would simulate code paths for the case that the return
         * statement does not exist.
         * @param uselessReturns The collected return statements.
         * @param prevSegments The previous segments to traverse.
         * @param [providedTraversedSegments] A set of segments that have already been traversed in this call
         * @returns `uselessReturns`.
         */
        function getUselessReturns(
            uselessReturns: Node[],
            prevSegments: CodePathSegment[],
            providedTraversedSegments?: WeakSet<CodePathSegment>,
        ) {
            const traversedSegments = providedTraversedSegments || new WeakSet();

            prevSegments.forEach((segment) => {
                if (!segment.reachable) {
                    if (!traversedSegments.has(segment)) {
                        traversedSegments.add(segment);
                        getUselessReturns(
                            uselessReturns,
                            segment.allPrevSegments.filter(isReturned),
                            traversedSegments,
                        );
                    }
                    return;
                }

                uselessReturns.push(...segmentInfoMap.get(segment)!.uselessReturns);
            });

            return uselessReturns;
        }

        /**
         * Removes the return statements on the given segment from the useless return
         * statement list.
         *
         * This segment may be an unreachable segment.
         * In that case, the information object of the unreachable segment is not
         * initialized because `onCodePathSegmentStart` event is not notified for
         * unreachable segments.
         * This goes to the previous segments of the unreachable segment recursively
         * if the unreachable segment was generated by a return statement. Otherwise,
         * this ignores the unreachable segment.
         *
         * This behavior would simulate code paths for the case that the return
         * statement does not exist.
         * @param segment The segment to get return statements.
         * @param usedUnreachableSegments A set of segments that have already been traversed in this call.
         */
        function markReturnStatementsOnSegmentAsUsed(
            segment: CodePathSegment,
            usedUnreachableSegments: Set<CodePathSegment>,
        ) {
            if (!segment.reachable) {
                usedUnreachableSegments.add(segment);
                segment.allPrevSegments
                    .filter(isReturned)
                    .filter((prevSegment) => !usedUnreachableSegments.has(prevSegment))
                    .forEach((prevSegment) => markReturnStatementsOnSegmentAsUsed(
                        prevSegment,
                        usedUnreachableSegments,
                    ));
                return;
            }

            const info = segmentInfoMap.get(segment);

            info!.uselessReturns = info!.uselessReturns.filter((node: Node) => {
                if (
                    scopeInfo!.traversedTryBlockStatements
                    && scopeInfo!.traversedTryBlockStatements.length > 0
                ) {
                    const returnInitialRange = node.range[0];
                    const returnFinalRange = node.range[1];

                    const areBlocksInRange = scopeInfo!.traversedTryBlockStatements.some(
                        (tryBlockStatement) => {
                            const blockInitialRange = tryBlockStatement.range[0];
                            const blockFinalRange = tryBlockStatement.range[1];

                            return (
                                returnInitialRange >= blockInitialRange
                                && returnFinalRange <= blockFinalRange
                            );
                        },
                    );

                    if (areBlocksInRange) {
                        return true;
                    }
                }

                remove(scopeInfo!.uselessReturns, node);
                return false;
            });
        }

        /**
         * Removes the return statements on the current segments from the useless
         * return statement list.
         *
         * This function will be called at every statement except FunctionDeclaration,
         * BlockStatement, and BreakStatement.
         *
         * - FunctionDeclarations are always executed whether it's returned or not.
         * - BlockStatements do nothing.
         * - BreakStatements go the next merely.
         */
        function markReturnStatementsOnCurrentSegmentsAsUsed() {
            scopeInfo!.currentSegments.forEach((segment: CodePathSegment) => {
                markReturnStatementsOnSegmentAsUsed(segment, new Set());
            });
        }

        //----------------------------------------------------------------------
        // Public
        //----------------------------------------------------------------------

        return {
            // Makes and pushes a new scope information.
            onCodePathStart(codePath: CodePath) {
                scopeInfo = {
                    upper: scopeInfo,
                    uselessReturns: [],
                    traversedTryBlockStatements: [],
                    codePath,
                    currentSegments: new Set(),
                };
            },

            // Reports useless return statements if exist.
            onCodePathEnd() {
                scopeInfo!.uselessReturns.forEach((node) => {
                    context.report({
                        node,
                        loc: node.loc,
                        messageId: 'unnecessaryReturn',
                        fix(fixer: Fixer) {
                            if (
                                isRemovable(node)
                                && !sourceCode.getCommentsInside(node).length
                            ) {
                                /**
                                 * Extend the replacement range to include the
                                 * entire function to avoid conflicting with
                                 * no-else-return.
                                 * https://github.com/eslint/eslint/issues/8026
                                 */
                                return new FixTracker(fixer, sourceCode)
                                    .retainEnclosingFunction(node)
                                    .remove(node);
                            }
                            return null;
                        },
                    });
                });

                scopeInfo = scopeInfo!.upper;
            },

            /**
             * Initializes segments.
             * NOTE: This event is notified for only reachable segments.
             * @param segment The control flow segment.
             */
            onCodePathSegmentStart(segment: CodePathSegment) {
                scopeInfo!.currentSegments.add(segment);

                const info = {
                    uselessReturns: getUselessReturns([], segment.allPrevSegments),
                    returned: false,
                };

                // Stores the info.
                segmentInfoMap.set(segment, info);
            },

            onUnreachableCodePathSegmentStart(segment: CodePathSegment) {
                scopeInfo!.currentSegments.add(segment);
            },

            onUnreachableCodePathSegmentEnd(segment: CodePathSegment) {
                scopeInfo!.currentSegments.delete(segment);
            },

            onCodePathSegmentEnd(segment: CodePathSegment) {
                scopeInfo!.currentSegments.delete(segment);
            },

            // Adds ReturnStatement node to check whether it's useless or not.
            ReturnStatement(node: Node<'ReturnStatement'>) {
                if (node.argument) {
                    markReturnStatementsOnCurrentSegmentsAsUsed();
                }
                if (
                    node.argument
                    || astUtils.isInLoop(node)
                    || isInFinally(node)
                    // Ignore `return` statements in unreachable places
                    // (https://github.com/eslint/eslint/issues/11647).
                    || !isAnySegmentReachable(scopeInfo!.currentSegments)
                ) {
                    return;
                }

                Array.from(scopeInfo!.currentSegments).forEach((segment) => {
                    const info = segmentInfoMap.get(segment);

                    if (info) {
                        info.uselessReturns.push(node);
                        info.returned = true;
                    }
                });
                scopeInfo!.uselessReturns.push(node);
            },

            'TryStatement > BlockStatement.block:exit':
                function onTryStatementBlockStatementBlockExit(node: Node<'BlockStatement'>) {
                    scopeInfo!.traversedTryBlockStatements.push(node);
                },

            'TryStatement:exit': function onTryStatementExit() {
                scopeInfo!.traversedTryBlockStatements.pop();
            },

            /**
             * Registers for all statement nodes except FunctionDeclaration, BlockStatement, BreakStatement.
             * Removes return statements of the current segments from the useless return statement list.
             */
            ClassDeclaration: markReturnStatementsOnCurrentSegmentsAsUsed,
            ContinueStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            DebuggerStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            DoWhileStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            EmptyStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ExpressionStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ForInStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ForOfStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ForStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            IfStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ImportDeclaration: markReturnStatementsOnCurrentSegmentsAsUsed,
            LabeledStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            SwitchStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ThrowStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            TryStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            VariableDeclaration: markReturnStatementsOnCurrentSegmentsAsUsed,
            WhileStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            WithStatement: markReturnStatementsOnCurrentSegmentsAsUsed,
            ExportNamedDeclaration: markReturnStatementsOnCurrentSegmentsAsUsed,
            ExportDefaultDeclaration: markReturnStatementsOnCurrentSegmentsAsUsed,
            ExportAllDeclaration: markReturnStatementsOnCurrentSegmentsAsUsed,
        };
    },
};

export default rule;
